def parse_args():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("fsm", help="Input FSM file (xlsx)")
    parser.add_argument("-o", "--output", required=True, help="Base filename (generates base.h, base.cpp, etc.)")
    parser.add_argument("-s", "--split-files", type=int, help="Number of files to emit", default=1)
    return parser.parse_args()


class Fsm:
    OPCODE_RENAMES = {
        "AtomicStoreAdd": "AtomicStore_ADD",
        "AtomicStoreClr": "AtomicStore_CLR",
        "AtomicStoreEor": "AtomicStore_EOR",
        "AtomicStoreSet": "AtomicStore_SET",
        "AtomicStoreSmax": "AtomicStore_SMAX",
        "AtomicStoreSmin": "AtomicStore_SMIN",
        "AtomicStoreUmax": "AtomicStore_UMAX",
        "AtomicStoreUmin": "AtomicStore_UMIN",
        "AtomicLoadAdd": "AtomicLoad_ADD",
        "AtomicLoadClr": "AtomicLoad_CLR",
        "AtomicLoadEor": "AtomicLoad_EOR",
        "AtomicLoadSet": "AtomicLoad_SET",
        "AtomicLoadSmax": "AtomicLoad_SMAX",
        "AtomicLoadSmin": "AtomicLoad_SMIN",
        "AtomicLoadUmax": "AtomicLoad_UMAX",
        "AtomicLoadUmin": "AtomicLoad_UMIN",
        "SI.Opcode.Req.Opcode": "SI.Opcode",  # 4 TxReqOpcode have this crazy syntax
    }
    ORDER_RENAMES = {"NOR": "NoOrder", "RQA": "RequestAccepted", "RQO": "RequestOrder", "EPO": "EndpointOrder"}
    CACHESTATE_RENAMES = {"!SC": "UD|UC|SD|I"}

    def __init__(self, xlsx_file, sheet_name):
        df = self._read_table(xlsx_file, sheet_name)
        df = self._remove_unneeded_rows(df)
        df = self._rename_elements(df)
        df = self._expand_rows(df)
        df = self._rename_elements(df)  # Sometimes expanded rows also contain elements that need to be renamed

        # TODO Removing opcodes that == x, these are RAS
        df = df.loc[(df[("SI", "Opcode")] != "x")]
        self.df = df

    def _read_table(self, xlsx_file, sheet_name):
        df = pd.read_excel(xlsx_file, sheet_name=sheet_name, engine="openpyxl", keep_default_na=False, skiprows=4)

        # Create multindex for referencing the columns
        indexes = list(zip(df.iloc[0], df.iloc[2]))

        # PHA Type is an input
        indexes = [("SI", "PHA") if i[1] == "PHA" else i for i in indexes]
        # TotalSNo is an output
        tuples = [("SO", "TotalSNo") if i[1] == "TotalSNo" else i for i in indexes]

        index = pd.MultiIndex.from_tuples(tuples, names=["IN_OUT", "TYPE"])
        df.columns = index

        # First 4 rows are notes, drop them
        df.drop(df.index[0:3], inplace=True)

        return df

    # Remove FSM visual separators, we are only concerned with rows that
    # have pipeline passes (PipelinePass != 0 or 99)
    def _remove_unneeded_rows(self, df):
        drop_filter = ~df[("SI", "PipelinePass")].isin([99, 0, ""])
        return df.loc[drop_filter]

    # Columns have shorthand that need to be expanded.  For instance (Opcode = "ReadClean|ReadNotSharedDirty")
    def _expand_rows(self, df):
        # Expand any rows that have | symbol
        cols = [
            ("SI", "Opcode"),
            ("SI", "Order"),
            ("SI", "CacheState"),
            ("SI", "AdbState"),
            ("SI", "DatTagOp"),
            ("SI", "SfCmd"),
            ("SI", "RasAction"),
        ]
        for col in cols:
            df[col] = df[col].str.split("|")
            df = df.explode(col)

        # Expand any rows that have a 0r or 1r.
        df_or_filt = df.isin(["1r", "0r"]).any(axis=1)
        df_ors = df[df_or_filt]  # Contains df of only rows that have 1r or 0r
        df = df[~df_or_filt]

        new_rows = list()
        for _, row in df_ors.iterrows():
            original_row = row.to_dict()

            # Find columns that have 0r or 1r in them
            or_columns = list()
            for (col, col1), val in original_row.items():
                if val == "1r" or val == "0r":
                    or_columns.append(((col, col1), val[0]))  # strip r

            # Create a duplicate of each row with only one column set
            for idx in range(len(or_columns)):
                # This is the element we are keeping constant, the rest of the
                # or columns are being changed to don't care
                (static_col, static_col1), static_val = or_columns[idx]
                new_row = original_row.copy()
                for (col, col1), _ in or_columns:
                    new_row[(col, col1)] = "x"
                new_row[(static_col, static_col1)] = static_val
                new_rows.append(new_row)

        new_df = pd.DataFrame(new_rows)
        df = pd.concat([df, new_df])
        return df

    def _rename_elements(self, df):
        def strip(value):
            if len(value) > 0 and value[0] != "{":
                value = re.sub(r"(^_)*_.*", "\\1", value)  # Strip everything after underscore
                value = re.sub(r"(^ )* .*", "\\1", value)  # Strip everything after space
            return value

        cols = [
            ("SI", "Opcode"),
            ("SO", "TxReqOpcode"),
            ("SO", "TxRsp0Opcode"),
            ("SO", "TxRsp1Opcode"),
            ("SO-D", "TxDatOpcode"),
            ("SO", "TxRsp1TgtID"),
            ("SO-D", "TxDatOpcode"),
            ("SO-D", "TxDatTgtID"),
        ]
        for col in cols:
            df[col] = df[col].apply(strip)
            df[col] = df[col].replace(self.OPCODE_RENAMES)
        df[("SI", "Order")] = df[("SI", "Order")].replace(self.ORDER_RENAMES)
        df[("SO", "TxReqOrder")] = df[("SO", "TxReqOrder")].replace(self.ORDER_RENAMES)
        df[("SI", "CacheState")] = df[("SI", "CacheState")].replace(self.CACHESTATE_RENAMES)
        return df


